const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centerPoint = ee.Geometry.Point([-73.845369, -9.799994]);
  const roi = centerPoint.buffer(5000); // 5km radius

  const date2017 = '2017-08-23';
  const date2022 = '2022-08-21';
  const dateWindow = 15; // days window for cloud-free images

  // 2. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Data Acquisition for 2017
  let col2017 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(roi)
    .filterDate(ee.Date(date2017).advance(-dateWindow, 'day'), 
                ee.Date(date2017).advance(dateWindow, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds);

  const size2017 = col2017.size().getInfo();
  console.log(`2017 Images found: ${size2017}`);

  if (size2017 === 0) {
    // Try Landsat 8 as fallback
    col2017 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(ee.Date(date2017).advance(-dateWindow, 'day'), 
                  ee.Date(date2017).advance(dateWindow, 'day'))
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const size2017_ls = col2017.size().getInfo();
    console.log(`2017 Landsat fallback: ${size2017_ls}`);

    if (size2017_ls === 0) {
      console.log("No data for 2017");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 4. Data Acquisition for 2022
  let col2022 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(roi)
    .filterDate(ee.Date(date2022).advance(-dateWindow, 'day'), 
                ee.Date(date2022).advance(dateWindow, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds);

  const size2022 = col2022.size().getInfo();
  console.log(`2022 Images found: ${size2022}`);

  if (size2022 === 0) {
    console.log("No data for 2022");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Calculate NDVI and forest area
  function calculateForestArea(collection) {
    const composite = collection.median();
    const ndvi = composite.normalizedDifference(['B8', 'B4']).rename('NDVI');
    const forest = ndvi.gt(0.6); // Forest threshold

    // Count forest pixels
    const stats = forest.reduceRegion({
      reducer: ee.Reducer.sum().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: roi,
      scale: 3000,
      maxPixels: 1e9
    });

    return stats;
  }

  const stats2017 = calculateForestArea(col2017);
  const forestArea2017 = stats2017.get('NDVI_sum').getInfo();
  const pixelCount2017 = stats2017.get('NDVI_count').getInfo();

  console.log(`2017: Forest pixels=${forestArea2017}, Total pixels=${pixelCount2017}`);

  if (pixelCount2017 === 0) {
    console.log("No valid pixels for 2017 after masking");
    console.log("<answer>C2</answer>");
    return;
  }

  const stats2022 = calculateForestArea(col2022);
  const forestArea2022 = stats2022.get('NDVI_sum').getInfo();
  const pixelCount2022 = stats2022.get('NDVI_count').getInfo();

  console.log(`2022: Forest pixels=${forestArea2022}, Total pixels=${pixelCount2022}`);

  if (pixelCount2022 === 0) {
    console.log("No valid pixels for 2022 after masking");
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Validation & Final Answer
  if (forestArea2017 === null || forestArea2022 === null || 
      isNaN(forestArea2017) || isNaN(forestArea2022)) {
    console.log("Calculation failed");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Forest area comparison: 2022=${forestArea2022.toFixed(0)} vs 2017=${forestArea2017.toFixed(0)}`);

  if (forestArea2022 > forestArea2017) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
